global.schema:
type RoleBasedAuthState {
  creator: String
  admins: [String!]!
  members: [String!]!
  notes: [Note!]!
}

type Note {
  id: String!
  author: String!
  text: String!
  createdAt: String!
}

operations.reducer:
const address = action.context?.signer?.user?.address;
if (!address) {
  throw new NotAuthorizedError("User is not authenticated");
}
if (state.creator) {
  throw new AlreadyBootstrappedError("Document already bootstrapped");
}
state.creator = address;
state.admins.push(address);

const address = action.context?.signer?.user?.address;
if (!address) {
  throw new NotAuthorizedError("User is not authenticated");
}
if (!state.admins.includes(address)) {
  throw new NotAdminError(`${address} is not an admin`);
}
const target = action.input.address;
if (state.admins.includes(target)) {
  return;
}
state.admins.push(target);
state.members = state.members.filter((m) => m !== target);

const address = action.context?.signer?.user?.address;
if (!address) {
  throw new NotAuthorizedError("User is not authenticated");
}
if (!state.admins.includes(address)) {
  throw new NotAdminError(`${address} is not an admin`);
}
const target = action.input.address;
if (target === state.creator) {
  throw new CannotRevokeCreatorError("The creator cannot be demoted");
}
if (state.admins.length === 1 && state.admins[0] === target) {
  throw new LastAdminError("Cannot remove the last admin");
}
state.admins = state.admins.filter((a) => a !== target);

const address = action.context?.signer?.user?.address;
if (!address) {
  throw new NotAuthorizedError("User is not authenticated");
}
if (!state.admins.includes(address)) {
  throw new NotAdminError(`${address} is not an admin`);
}
const target = action.input.address;
if (state.admins.includes(target)) {
  throw new AddressAlreadyAdminError(`${target} is already an admin`);
}
if (state.members.includes(target)) {
  return;
}
state.members.push(target);

const address = action.context?.signer?.user?.address;
if (!address) {
  throw new NotAuthorizedError("User is not authenticated");
}
if (!state.admins.includes(address)) {
  throw new NotAdminError(`${address} is not an admin`);
}
const target = action.input.address;
state.members = state.members.filter((m) => m !== target);

operations.schema:
input WriteNoteInput {
  id: String!
  text: String!
  createdAt: String!
}

operations.reducer:
const address = action.context?.signer?.user?.address;
if (!address) {
  throw new NotAuthorizedError("User is not authenticated");
}
const isAdmin = state.admins.includes(address);
const isMember = state.members.includes(address);
if (!isAdmin && !isMember) {
  throw new NotAuthorizedError(`${address} has no role`);
}
state.notes.push({
  id: action.input.id,
  author: address,
  text: action.input.text,
  createdAt: action.input.createdAt,
});
